function promotionContent(d){if(typeof d.promoContent!=='string'){const plan=d.promoPlan||d.answers?.[3]||d.notes?.[3]||'';d.promoContent=[plan,d.message&&d.message!==plan?'핵심 메시지: '+d.message:''].filter(Boolean).join('\n\n');}return d.promoContent;}
const musicGenres={'댄스 팝':'밝은 신스, 탄력 있는 전자 드럼, 기억하기 쉬운 후렴.','팝':'선명한 멜로디, 안정적인 드럼과 베이스, 친근한 보컬과 후렴.','합창':'여러 목소리가 어우러지는 화음, 명료한 가사 전달, 함께 부르기 쉬운 후렴.','국악 퓨전':'가야금·해금 등 국악기와 현대 리듬 악기의 조화, 한국어의 자연스러운 운율.','어쿠스틱':'따뜻한 통기타와 피아노, 절제된 타악기, 가까이 들리는 자연스러운 보컬.'};
function musicPrompt(){const d=draft(),t=topics[state.topic],detail=policyDetails[state.topic];const genre=Object.hasOwn(musicGenres,d.creativeStyle)?d.creativeStyle:'댄스 팝';const material=promotionContent(d)||[t[7],...detail.measures,'시민 편익: '+detail.change].join('\n');return `[서울 정책 홍보 브리프]
비전: G3 서울플랜 — 글로벌 TOP, 삶의 질 특별시 서울
분야: ${groups[t[1]][0]}
실습 조: ${state.topic+1}조\n정책: ${t[0]}
대상: ${d.audience||'서울시민'}
정책 내용과 시민 편익(참고 자료):
${material}


[공통 원칙]
입력 자료에 근거해 서울시가 무엇을 실행하고 시민의 일상이 어떻게 좋아질 수 있는지 알리세요. 확인되지 않은 성과·수치·일정·후기·신청 링크는 만들지 마세요. 정책 제안과 확정 사실, 기대효과를 구분하세요. 쉽고 명료한 한국어를 사용하세요. 참고 자료에 다른 정책의 내용이 섞여 있으면 선택한 정책에 해당하는 내용만 사용하세요.

선택한 홍보송 장르: ${genre} — ${musicGenres[genre]} 이 장르의 리듬·악기·보컬 특성을 실제 음악 설정에 반영하세요. 장르를 임의로 다른 것으로 바꾸지 마세요.
약 2분(120초) 분량의 독창적인 한국어 가사 전체를 작성하세요. Intro → Verse 1 → Pre-Chorus → Chorus → Verse 2 → Bridge → Final Chorus → Outro로 구성하고 반복 후렴도 생략하지 마세요. '삶의 질 특별시 서울'을 자연스러운 후렴에 담고 정책 대안과 시민 편익을 표현하세요. 특정 가수나 기존 곡을 모방하지 마세요.
Flow Music에 그대로 붙여넣을 수 있도록 장르·악기 등 음악 설정과 약 2분 분량의 전체 가사를 하나의 마크다운 코드블록(text)에 함께 담으세요. 복사할 내용은 코드블록 밖으로 나누지 마세요. [음악 설정]에는 곡 제목, 장르, BPM, 박자, 조성, 악기별 역할, 그루브, 보컬·화음·발음, 분위기, 편곡·믹싱, 구간별 예상 시간(합계 약 120초)을 작성하세요. [가사]에는 완성 가사 전체를 담으세요. 설정과 구간 이름은 노래하지 않고 가사만 한국어로 부르도록 지시하세요. 길이는 목표이며 서비스 전용 문법이나 기능을 추측하지 마세요.`;}
const videoAudiences={'사업에 맞게 자동 구성':'사업 대상과 이용 상황을 근거로 성별과 연령대를 선정하세요.','남녀 함께':'사업 대상에 해당하는 남성과 여성을 함께 구성하고 연령대는 사업에 맞추세요.','남성 이용자':'남성 이용자를 중심으로 하되 실제 사업 대상에 해당하는 연령대를 선정하세요.','여성 이용자':'여성 이용자를 중심으로 하되 실제 사업 대상에 해당하는 연령대를 선정하세요.'};
const videoDirections={'리듬 광고':'시민의 행동을 음악 박자에 맞춰 연결하는 빠르고 경쾌한 동작 연결 편집. 밝고 활기찬 정책 광고.','시네마틱':'서비스 공간과 이용 과정을 영화처럼 담고, 깊이 있는 빛과 자연스러운 장면 연결로 시민의 변화를 전달하는 광고.','브이로그':'시민이 서비스를 이용하는 과정을 가까이 따라가며 생생하게 전달하는 이용 체험형 광고.','다큐멘터리':'관찰하는 시선과 자연스러운 행동, 현장 소리를 중심으로 변화를 보여주는 기록 형식의 광고. 실제 인터뷰나 실적으로 오인시키지 않는다.','애니메이션':'고정된 캐릭터 디자인과 일관된 그림체, 명확한 움직임으로 정책의 변화를 보여주는 애니메이션 광고.'};
function videoFields(){const d=draft();return `<label for="videoAudience">서비스 이용자 구성</label><select id="videoAudience" data-field="videoAudience">${Object.keys(videoAudiences).map(x=>`<option ${x===(d.videoAudience||'사업에 맞게 자동 구성')?'selected':''}>${x}</option>`).join('')}</select>${field('서비스·이용 상황 추가 요청','videoServiceDetail',d.videoServiceDetail||'',true,'강조할 서비스, 이용 상황, 대상 연령대 등을 적으세요. 비워두면 사업 내용에 맞춰 구성합니다.')}<div class="hint">10초씩 3장면 · 총 30초<br>사업의 성격에 맞는 이용자를 설정하고, 서비스 제공 과정과 시민 편익을 중심으로 구성합니다.</div>`;}
function videoPrompt(){const d=draft(),t=topics[state.topic],detail=policyDetails[state.topic];const style=Object.hasOwn(videoDirections,d.creativeStyle)?d.creativeStyle:'리듬 광고';const audience=Object.hasOwn(videoAudiences,d.videoAudience)?d.videoAudience:'사업에 맞게 자동 구성';const material=promotionContent(d)||[t[7],...detail.measures,'시민 편익: '+detail.change].join('\n');return `[서울 정책 홍보 브리프]
비전: G3 서울플랜 — 글로벌 TOP, 삶의 질 특별시 서울
분야: ${groups[t[1]][0]}
실습 조: ${state.topic+1}조\n정책: ${t[0]}
대상: ${d.audience||'서울시민'}
정책 내용과 시민 편익(참고 자료):
${material}


[공통 원칙]
입력 자료에 근거해 서울시가 무엇을 실행하고 시민의 일상이 어떻게 좋아질 수 있는지 알리세요. 확인되지 않은 성과·수치·일정·후기·신청 링크는 만들지 마세요. 정책 제안과 확정 사실, 기대효과를 구분하세요. 쉽고 명료한 한국어를 사용하세요. 참고 자료에 다른 정책의 내용이 섞여 있으면 선택한 정책에 해당하는 내용만 사용하고, 정책과 맞지 않는 내용은 제작 메모에서 알려주세요.

[작성 언어]
영상 제작 프롬프트 전체를 한국어로 작성하세요. 장면 제목, 세 장면 코드블록 안의 연출·카메라·조명·음향·인물 설정·금지 사항까지 모두 한국어로 작성하세요. 영어 프롬프트나 영문 번역본을 별도로 제공하지 마세요. Flow AI 등 고유한 서비스 이름을 제외하고 전문 용어도 쉬운 한국어로 풀어 쓰세요. 코드블록을 그대로 복사하면 한국어 영상 제작 지시가 전달되도록 하세요. 등장인물의 대사 역시 한국어로 작성하세요.

[사업 대상과 서비스 이용자 설정]
이용자 구성: ${audience} — ${videoAudiences[audience]}
추가 요청: ${d.videoServiceDetail||'정책 내용에 맞는 서비스 이용 상황과 대상 연령대를 제안하세요.'}
먼저 입력 자료에서 사업의 목적, 핵심 서비스, 실제 지원 대상을 파악하세요. 이를 근거로 등장할 시민의 성별, 연령대(아동·청소년·청년·중장년·어르신), 이용 상황을 구체적으로 설정하세요. 전 시민 대상이면 남녀와 다양한 연령의 이용 모습을 자연스럽게 반영하고, 특정 대상 사업이면 해당 대상에 집중하세요. 예를 들어 청년 지원은 청년, 초등학생 학습 지원은 아동과 필요한 경우 보호자, 생활권 운동은 서비스 대상에 맞는 다양한 시민으로 구성하세요. 모든 사업에 남녀노소를 억지로 등장시키거나, 연령·성별에 관한 고정관념으로 역할을 정하지 마세요. 연출상 설정을 공식 지원 자격으로 표현하지 말고 확인되지 않은 자격은 단정하지 마세요.
인물은 서비스를 보여주는 이용자입니다. 단일 주인공의 외모·개인 서사·감정 연기에 집중하지 말고 서비스 공간, 제공 방식, 이용 행동과 편익을 화면의 중심에 두세요. 장면마다 사업에 맞는 다른 이용자를 등장시켜도 됩니다. 동일 인물이 다시 등장할 때만 외형·의상·목소리의 일관성을 유지하세요.

[영상 연출]
선택한 영상 연출: ${style} — ${videoDirections[style]}
선택한 연출을 촬영·편집·음악·전환에 적용하되 사업의 핵심 서비스가 명확히 드러나는 정책 광고를 설계하세요.
10초씩 3장면, 총 30초입니다. 하나의 핵심 서비스를 중심으로 1장면은 서비스와 이용 상황을 즉시 보여주고, 2장면은 실제 서비스 제공·이용 과정을 구체적인 행동으로 보여주며, 3장면은 그 서비스로 기대되는 시민 편익을 보여주세요. 매 장면에 서비스 공간·시설·도구·제공자와 이용자의 상호작용 등 사업의 특징이 드러나는 요소를 넣으세요. 확인되지 않은 이용 절차나 기능은 만들지 말고 제안인 경우 명확히 구분하세요. 문제를 길게 설명하거나 일반적인 드론 전경으로 채우지 마세요. 서울시의 실행 약속을 짧고 자신감 있는 한국어 대사로 담되 입력 자료로 확인되는 범위에서 작성하고, 모든 장면이 '서울시는'으로 시작하지 않게 하세요. 대사는 장면당 한 문장 이하로 10초 안에 자연스럽게 말할 수 있게 하세요.

[출력 형식]
Flow AI에 각각 붙여넣을 장면 프롬프트를 정확히 3개의 독립된 마크다운 코드블록(text)에 출력하세요. 장면별 제작 지시 전체를 각 코드블록 안에 넣어 한 번에 복사할 수 있게 하세요. 각 블록에 10초 길이, 시간별 행동과 촬영 구도, 카메라, 빛, 음향, 정확한 한국어 대사·화자, 강조할 서비스와 이용 과정, 해당 장면 이용자의 성별·연령대·역할·외형·의상·목소리, 시작·끝 화면, 글자 금지를 모두 반복하세요. 같은 인물이 재등장하면 앞 장면과 동일하다는 말로 설정을 생략하지 말고 반복하세요. 선택한 스타일에 맞춰 전환하되 각 장면은 과밀하지 않게 구성하세요. 영상에는 자막·캡션·화면 글자·로고·워터마크를 넣지 마세요.
제안 단계라면 제작 메모에 '교육용 정책 제안 · 공식 추진 여부 확인 필요'를 표시하고 영상에는 노출하지 마세요. 이 문구는 제안 단계인 경우에만 사용하세요. 다른 형식의 추가 코드블록은 만들지 마세요.`;}
const policyDetails=[{"purpose": "운동을 위해 멀리 이동해야 하는 불편을 줄이고, 집 가까이에서 꾸준히 건강을 관리할 수 있도록 합니다.", "measures": ["서울체력장 센터를 확대하고 찾아가는 서울체력장을 운영합니다.", "지하철 유휴공간을 활용한 펀스테이션을 자치구로 확산합니다.", "산림·공원·수변공간을 연결하는 건강활력 에코 플랫폼을 조성합니다."], "change": "퇴근길이나 집 근처에서 운동할 기회가 늘어납니다. 실제 체감을 위해서는 거리뿐 아니라 이용시간, 예약 편의와 접근성도 함께 살펴봐야 합니다.", "pages": "3쪽"}, {"purpose": "시간과 장소에 관계없이 안심할 수 있도록 생활 주변의 위험요인을 줄입니다.", "measures": ["사고가 잦은 스쿨존의 보행로와 차로를 분리합니다.", "서울안심벨과 지능형 CCTV 등 생활밀착형 안전 기반을 확대합니다.", "골목길 빛환경을 개선해 어두운 귀갓길의 안전을 강화합니다."], "change": "등하굣길과 심야 귀갓길 등 일상의 이동에서 불안을 줄이는 데 목적이 있습니다. 시설 설치와 함께 시민이 위치와 사용법을 알고 있는지도 중요합니다.", "pages": "4쪽"}, {"purpose": "외로움을 겪는 시민이 생활권 안에서 사람을 만나고 일상의 관계를 회복하도록 돕습니다.", "measures": ["서울마음편의점을 전 자치구로 확대합니다.", "연령별 특화프로그램을 마련해 다양한 시민의 참여를 돕습니다.", "서울 솔로 밥상동행으로 함께 식사하고 교류하는 기회를 제공합니다."], "change": "혼자 지내는 시민에게 부담 없이 방문하고 대화할 수 있는 접점이 생깁니다. 한 번의 행사 참여가 지속적인 관계로 이어지는지가 핵심입니다.", "pages": "4쪽"}, {"purpose": "온라인 학습만으로 해결하기 어려운 학습 지속과 질문 해소를 대면 코칭으로 지원합니다.", "measures": ["지역아동센터 10개소에서 시범 운영한 뒤 청소년·평생교육 시설 등으로 확대할 계획입니다.", "서울런쌤이 초등학생에게 맞춤형 그룹 멘토링을 제공합니다.", "보도자료는 가입 기준을 중위소득 80% 이하에서 100% 이하로 완화하는 계획을 제시합니다."], "change": "아이에게는 질문하고 학습 습관을 점검할 기회가, 보호자에게는 학습관리 부담을 덜 수 있는 지원이 생깁니다. 센터까지 이동하기 쉬운지도 살펴봐야 합니다.", "pages": "5쪽"}, {"purpose": "정비사업의 단계별 지연 요인을 줄여 주택이 계획적으로 공급될 수 있도록 합니다.", "measures": ["2031년까지 31만 호 착공을 목표로 합니다.", "핵심전략 정비구역에 표준처리기한제를 적용하고 공정촉진회의로 병목을 해소합니다.", "추진위원회 구성 동의율이 75%를 넘는 사업지에 정비사업 하이패스를 적용해 조합 설립 기간 단축을 추진합니다."], "change": "주민이 사업 진행을 예측하고 주거 계획을 세울 수 있도록 돕는 정책입니다. 착공 목표는 입주 완료와 다르며, 실제 일정은 사업지별로 확인해야 합니다.", "pages": "6쪽"}, {"purpose": "생애주기에 맞는 주거지원을 넓히고, 전세 계약 전후의 위험을 줄이는 주거안전망을 만듭니다.", "measures": ["청년·신혼부부·어르신 등 생애주기별 주거지원을 확대합니다.", "계약 전 위험분석으로 위험요인을 확인하도록 지원합니다.", "계약 당일 주거안심매니저 동행과 계약 후 반환보증료 지원을 연결합니다."], "change": "첫 계약을 준비하는 시민이 복잡한 정보를 혼자 판단하는 부담을 줄일 수 있습니다. 지원 이용이 모든 계약의 안전을 보장한다는 뜻은 아니며, 대상과 절차를 확인해야 합니다.", "pages": "6쪽"}, {"purpose": "청년이 AI 역량과 일 경험을 쌓아 취업과 창업의 기회를 넓히도록 지원합니다.", "measures": ["소득에 관계없이 청년 50만 명에게 AI 이용권과 무료 기초교육을 제공하는 계획입니다.", "AI 교육을 직무경험 및 전문교육과 연계합니다.", "교육·일자리·주거정책을 연결해 청년의 자립을 뒷받침합니다."], "change": "유료 도구 비용의 부담을 낮추고 배운 내용을 실제 업무에 적용할 기회를 넓힙니다. 도구 이용 자체를 넘어 프로젝트 경험과 직무역량으로 이어지는지가 중요합니다.", "pages": "7쪽"}, {"purpose": "밤 시간을 문화·관광·상권의 활력으로 연결하면서 이동과 안전도 함께 개선합니다.", "measures": ["체육·문화시설 운영시간을 늘리고 한강·남산·DDP 등에 야간 체류형 콘텐츠를 확대합니다.", "달빛야장 시범 운영을 거쳐 자치구로 확산하는 계획입니다.", "심야버스와 CCTV를 확충해 야간 활동을 지원합니다."], "change": "시민과 방문객이 밤에도 머물고 즐길 선택지가 늘어납니다. 상권 활성화와 함께 귀가 교통, 주변 거주민의 불편, 운영 여건을 함께 고려해야 합니다.", "pages": "7~8쪽"}, {"purpose": "주거·일자리·배움·문화를 서울 전역에 고르게 배치해 생활권 가까이에서 기회를 누리도록 합니다.", "measures": ["철도차량기지 등 가용부지에 주거·일자리·커뮤니티 공간을 결합한 청년미래타운을 추진합니다.", "상암·수색, 가산·구로, 창동·상계, 고덕·강일을 4광역도심으로 육성합니다.", "지역 산업·대학·창업 생태계와 연결하고 생활권에 보행일상중심을 조성합니다."], "change": "사는 곳과 일하고 배우는 곳의 거리를 줄이는 방향입니다. 거점을 만드는 것과 함께 실제 일자리, 생활서비스, 교통이 연결되는지가 중요합니다.", "pages": "8~9쪽"}, {"purpose": "자율주행 기술을 대중교통에 적용하고, 새벽·심야 등 이동의 공백을 줄이는 방향으로 운행을 확대합니다.", "measures": ["2030년까지 자율주행버스를 500대로 확대하는 목표입니다.", "평일 심야·새벽 중심 운영에서 안전성 검증을 거쳐 단계적으로 운영시간을 확대합니다.", "기술 실증과 제도 정비를 통해 시내버스의 자율주행버스 비율을 단계적으로 높입니다."], "change": "첫차 이전에 출근하거나 늦게 귀가하는 시민의 이동 선택지를 넓히는 데 도움이 될 수 있습니다. 안전성, 실제 노선, 배차와 정류장 접근성을 함께 확인해야 합니다.", "pages": "9쪽"}];
